#!/usr/bin/env node
/**
 * EHL loyalty bonus report (LOCAL ONLY, lives in gitignored .claude/).
 *
 * Reads the database (GET requests only, never writes) and produces:
 *   - out/data.json      raw snapshot of everything read
 *   - out/analysis.json  per-team rosters, roster changes, bonus results, leaderboards
 *   - out/report.html    phone-friendly report (publish it as an Artifact if wanted)
 *   - a console summary
 *
 * Usage (from repo root):
 *   node .claude/loyalty-bonus/loyalty-report.mjs [--env .env.local] [--out <dir>]
 *        [--exclude-finale] [--finale-spots 15] [--offline]
 *
 *   --env             env file with NEXT_PUBLIC_SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY
 *   --out             output dir (default .claude/loyalty-bonus/out)
 *   --exclude-finale  do not count the Grand Finale as a match
 *   --finale-spots    how many leaderboard places qualify (default 15)
 *   --offline         reuse out/data.json instead of querying again
 *
 * See README.md next to this file for the rules, assumptions and caveats.
 */
import fs from "fs";
import path from "path";

// ─── Config ──────────────────────────────────────────────────
const RULES = {
  threeMatch: { points: 6, matches: 3, countries: 2 },
  fullSeason: { points: 10 },
};
// Match 1 (Munich Makeathon, run on Tally) has EMPTY challenge_registrations.roster.
// Its teams were imported into team_members on this date by scripts/import-team-members.ts,
// so "joined on this date" = was on the Makeathon team. Used only for chapters whose
// registrations have no stored roster.
const MAKEATHON_IMPORT_DATE = "2026-05-26";

const args = process.argv.slice(2);
const arg = (name, def) => {
  const i = args.indexOf(name);
  return i === -1 ? def : args[i + 1];
};
const flag = (name) => args.includes(name);
const HERE = path.dirname(new URL(import.meta.url).pathname);
const OUT = path.resolve(arg("--out", path.join(HERE, "out")));
const ENV_FILE = path.resolve(arg("--env", ".env.local"));
const EXCLUDE_FINALE = flag("--exclude-finale");
const FINALE_SPOTS = Number(arg("--finale-spots", "15"));
fs.mkdirSync(OUT, { recursive: true });

// ─── Read (GET only) ─────────────────────────────────────────
async function load() {
  if (flag("--offline")) return JSON.parse(fs.readFileSync(path.join(OUT, "data.json"), "utf8"));
  // Line-based parser: .env.local contains multi-line JSON values that break `source`.
  const env = Object.fromEntries(
    fs.readFileSync(ENV_FILE, "utf8").split("\n")
      .map((l) => l.match(/^([A-Z_]+)=(.*)$/)).filter(Boolean)
      .map((m) => [m[1], m[2].replace(/^["']|["']$/g, "")])
  );
  const U = env.NEXT_PUBLIC_SUPABASE_URL, K = env.SUPABASE_SERVICE_ROLE_KEY;
  if (!U || !K) throw new Error(`Missing Supabase URL/service key in ${ENV_FILE}`);
  // PostgREST caps responses at 1000 rows, so page with Range headers.
  async function all(q) {
    let out = [];
    for (let o = 0; ; o += 1000) {
      const r = await fetch(`${U}/rest/v1/${q}`, {
        method: "GET",
        headers: { apikey: K, Authorization: `Bearer ${K}`, Range: `${o}-${o + 999}` },
      });
      const j = await r.json();
      if (!Array.isArray(j)) throw new Error(`${q}: ${JSON.stringify(j)}`);
      out = out.concat(j);
      if (j.length < 1000) break;
    }
    return out;
  }
  const chapters = await all("chapters?select=id,name,city,country,match_number,status,date,is_finale&order=match_number");
  const emptyRosterChapters = new Set();
  const d = {
    fetchedAt: new Date().toISOString(),
    chapters,
    teams: await all("teams?select=id,name,status,president_user_id"),
    members: await all("team_members?select=team_id,user_id,role,joined_at"),
    regs: await all("challenge_registrations?select=chapter_id,team_id,roster"),
    scores: await all("scores?select=chapter_id,team_id,placement,points,published"),
    lb: await all("leaderboard?select=team_id,team_name,total_points,best_finish,matches_played"),
    profiles: await all("profiles?select=id,email"),
    events: await all("event_log?select=action,entity_id,delta,created_at&action=in.(team.member_removed,team.member_moved)"),
    checkedInApps: {},
  };
  for (const r of d.regs) if (!r.roster || r.roster.length === 0) emptyRosterChapters.add(r.chapter_id);
  for (const cid of emptyRosterChapters) {
    d.checkedInApps[cid] = (await all(`applications?select=email&status=eq.checked_in&chapter_id=eq.${cid}`))
      .map((a) => a.email.toLowerCase().trim());
  }
  fs.writeFileSync(path.join(OUT, "data.json"), JSON.stringify(d));
  return d;
}

// ─── Analysis ────────────────────────────────────────────────
function analyse(d) {
  const counted = d.chapters.filter((c) => c.status === "completed" && !(EXCLUDE_FINALE && c.is_finale));
  const ch = Object.fromEntries(counted.map((c) => [c.id, c]));
  const email = Object.fromEntries(d.profiles.map((p) => [p.id, (p.email || "").toLowerCase().trim()]));
  const teamName = Object.fromEntries(d.teams.map((t) => [t.id, t.name]));
  const president = Object.fromEntries(d.teams.map((t) => [t.id, t.president_user_id]));
  const reconChapters = new Set(Object.keys(d.checkedInApps));

  function rosterFor(r) {
    if (r.roster && r.roster.length) return { roster: [...r.roster].sort(), recon: false };
    // Reconstruct: imported members still on the team + people who were later removed or
    // moved off the team and checked in at that event.
    const checked = new Set(d.checkedInApps[r.chapter_id] || []);
    const imported = d.members
      .filter((m) => m.team_id === r.team_id && m.joined_at.startsWith(MAKEATHON_IMPORT_DATE))
      .map((m) => m.user_id);
    const gone = [
      ...d.events.filter((e) => e.action === "team.member_removed" && e.entity_id === r.team_id)
        .map((e) => e.delta?.deleted?.user_id),
      ...d.events.filter((e) => e.action === "team.member_moved" && e.delta?.moved?.from_team === r.team_id)
        .map((e) => e.delta?.moved?.user_id),
    ].filter((u) => u && checked.has(email[u]));
    return { roster: [...new Set([...imported, ...gone])].sort(), recon: true };
  }

  const byTeam = {};
  for (const r of d.regs) {
    const c = ch[r.chapter_id];
    if (!c) continue;
    const s = d.scores.find((x) => x.team_id === r.team_id && x.chapter_id === r.chapter_id);
    (byTeam[r.team_id] ??= []).push({
      m: c.match_number, city: c.city, country: c.country, finale: !!c.is_finale,
      ...rosterFor(r), points: s?.points ?? null, placement: s?.placement ?? null,
    });
  }
  const teams = Object.entries(byTeam).map(([id, ms]) => ({
    id, name: teamName[id], president: president[id], matches: ms.sort((a, b) => a.m - b.m),
  }));

  // Roster changes
  const overlap = (a, b) => a.filter((x) => b.includes(x)).length;
  const kind = (a, b) => {
    const o = overlap(a, b);
    return o === a.length && o === b.length ? "identical" : o === 0 ? "none" : o === 1 ? "onlyOne" : "partial";
  };
  const transitions = { identical: 0, partial: 0, onlyOne: 0, none: 0 };
  const returning = teams.filter((t) => t.matches.length > 1).map((t) => {
    const steps = t.matches.slice(1).map((m, i) => {
      const prev = t.matches[i];
      const k = kind(prev.roster, m.roster);
      transitions[k]++;
      return { from: prev.m, to: m.m, kept: overlap(prev.roster, m.roster), kind: k };
    });
    const first = t.matches[0].roster, last = t.matches.at(-1).roster;
    return {
      id: t.id, name: t.name,
      matches: t.matches.map((m) => m.m), sizes: t.matches.map((m) => m.roster.length),
      countries: [...new Set(t.matches.map((m) => m.country))],
      steps, firstLastKept: overlap(first, last),
      allIdentical: steps.every((s) => s.kind === "identical"),
      presidentInAll: t.matches.every((m) => m.roster.includes(t.president)),
      usesReconstructed: t.matches.some((m) => m.recon),
    };
  });

  // Bonus
  const combos = (a, k) => (k === 0 ? [[]] : a.flatMap((x, i) => combos(a.slice(i + 1), k - 1).map((c) => [x, ...c])));
  const same = (g) => g.every((m) => m.roster.length === g[0].roster.length && m.roster.every((u) => g[0].roster.includes(u)));
  const core = (t, g) => {
    const c = g.map((m) => m.roster).reduce((a, r) => a.filter((x) => r.includes(x)));
    return c.length >= 2 && c.includes(t.president);
  };
  const seasonSize = counted.length;
  function bonus(t, rule) {
    const ok = (g) => (rule === "strict" ? same(g) : core(t, g));
    if (t.matches.length === seasonSize && ok(t.matches)) return RULES.fullSeason.points;
    for (const g of combos(t.matches, RULES.threeMatch.matches))
      if (new Set(g.map((m) => m.country)).size >= RULES.threeMatch.countries && ok(g)) return RULES.threeMatch.points;
    return 0;
  }
  const rank = (rows) => {
    rows = [...rows].sort((a, b) => b.pts - a.pts || (a.best ?? 99) - (b.best ?? 99) || a.name.localeCompare(b.name));
    let rk = 1;
    rows.forEach((r, i) => { if (i && (r.pts !== rows[i - 1].pts || r.best !== rows[i - 1].best)) rk = i + 1; r.rank = rk; });
    return rows;
  };
  // NOTE: the leaderboard view sums ALL published scores, including chapters excluded above.
  const lbRows = d.lb.map((r) => ({ id: r.team_id, name: r.team_name, pts: r.total_points, best: r.best_finish, bonus: 0 }));
  const base = rank(lbRows);
  const scenarios = {};
  for (const rule of ["strict", "core"]) {
    const b = Object.fromEntries(teams.map((t) => [t.id, bonus(t, rule)]));
    const table = rank(lbRows.map((r) => ({ ...r, bonus: b[r.id] || 0, pts: r.pts + (b[r.id] || 0) })));
    const inTop = (rows) => new Set(rows.filter((r) => r.rank <= FINALE_SPOTS).map((r) => r.id));
    const before = inTop(base), after = inTop(table);
    scenarios[rule] = {
      awards: teams.filter((t) => b[t.id]).map((t) => ({ id: t.id, name: t.name, bonus: b[t.id] })),
      table,
      enteredTop: table.filter((r) => after.has(r.id) && !before.has(r.id)).map((r) => r.name),
      leftTop: base.filter((r) => before.has(r.id) && !after.has(r.id)).map((r) => r.name),
    };
  }
  // Teams with an identical roster that are not (yet) eligible: future candidates / near misses.
  const nearMiss = returning.filter((r) => r.allIdentical && !scenarios.strict.awards.some((a) => a.id === r.id));

  return {
    generatedAt: new Date().toISOString(), fetchedAt: d.fetchedAt,
    countedMatches: counted.map((c) => ({ m: c.match_number, city: c.city, country: c.country, finale: !!c.is_finale, date: c.date })),
    reconstructedMatches: counted.filter((c) => reconChapters.has(c.id)).map((c) => c.match_number),
    stats: {
      teamsTotal: d.teams.length,
      teamsPlayed: teams.length,
      playedOnce: teams.filter((t) => t.matches.length === 1).length,
      returning: returning.length,
      byMatchCount: teams.reduce((m, t) => ((m[t.matches.length] = (m[t.matches.length] || 0) + 1), m), {}),
      transitions,
      completeChangeTeams: returning.filter((r) => r.steps.some((s) => s.kind === "none")).map((r) => r.name),
      onlyOneKeptTeams: returning.filter((r) => r.steps.some((s) => s.kind === "onlyOne")).map((r) => r.name),
      identicalTeams: returning.filter((r) => r.allIdentical).map((r) => r.name),
      firstVsLastNoOverlap: returning.filter((r) => r.firstLastKept === 0).map((r) => r.name),
      eligibleForThreeMatch: teams.filter((t) => t.matches.length >= 3 && new Set(t.matches.map((m) => m.country)).size >= 2).length,
      playedFullSeason: teams.filter((t) => t.matches.length === seasonSize).map((t) => t.name),
    },
    teams, returning, base, scenarios, nearMiss,
  };
}

// ─── HTML ────────────────────────────────────────────────────
function render(a) {
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const list = (xs) => (xs.length ? xs.map(esc).join(", ") : "none");
  const st = a.stats, T = st.transitions, S = a.scenarios;
  const baseRank = Object.fromEntries(a.base.map((r) => [r.id, r.rank]));
  const rowsShown = Math.max(FINALE_SPOTS + 5, 20);
  const table = (rows) => `<div class="tw"><table><thead><tr><th>#</th><th>Team</th><th class="r">Pts</th><th class="r">Move</th></tr></thead><tbody>${rows.slice(0, rowsShown).map((r) => {
    const dlt = baseRank[r.id] - r.rank;
    const mv = dlt > 0 ? `<span class="up">▲${dlt}</span>` : dlt < 0 ? `<span class="down">▼${-dlt}</span>` : `<span class="flat">–</span>`;
    return `<tr class="${r.bonus ? "hl" : ""}${r.rank > FINALE_SPOTS ? " out" : ""}"><td class="num">${r.rank}</td><td>${esc(r.name)}${r.bonus ? ` <span class="chip">+${r.bonus}</span>` : ""}</td><td class="r num">${r.pts}</td><td class="r num">${mv}</td></tr>`;
  }).join("")}</tbody></table></div>`;
  const tag = { identical: "same", partial: "2+ kept", onlyOne: "1 kept", none: "all new" };
  const teamRows = [...a.returning].sort((x, y) => y.matches.length - x.matches.length || x.name.localeCompare(y.name))
    .map((r) => `<tr><td>${esc(r.name)}</td><td class="num">${r.matches.map((m) => "M" + m).join(" ")}</td><td class="num">${r.sizes.join("/")}</td><td>${r.steps.map((s) => `<span class="st ${s.kind}">${tag[s.kind]}</span>`).join(" ")}</td></tr>`).join("");
  const awardLine = (pts) => {
    const xs = S.strict.awards.filter((x) => x.bonus === pts);
    return `<div class="award"><div><strong>${pts === RULES.fullSeason.points ? "Full season bonus" : "3-match bonus"}</strong><small>${list(xs.map((x) => x.name))}</small></div><div class="big${xs.length ? "" : " zero"}">+${pts} ×${xs.length}</div></div>`;
  };
  const impact = (sc) => `<ul style="margin-top:12px">${sc.awards.map((x) => {
    const r = sc.table.find((y) => y.id === x.id);
    return `<li><strong>${esc(x.name)}</strong> +${x.bonus}: rank ${baseRank[x.id]} → ${r.rank}</li>`;
  }).join("") || "<li>No team receives a bonus.</li>"}<li>Top ${FINALE_SPOTS}: ${sc.enteredTop.length || sc.leftTop.length ? `enters: ${list(sc.enteredTop)}; drops out: ${list(sc.leftTop)}` : "<strong>unchanged</strong>"}</li></ul>`;
  const total = T.identical + T.partial + T.onlyOne + T.none;
  const matchesLine = a.countedMatches.map((m) => `M${m.m} ${esc(m.city)} (${esc(m.country)})${m.finale ? " finale" : ""}`).join(", ");

  return `<title>EHL Loyalty Bonus</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@500;700&family=Outfit:wght@400;600;800&display=swap">
<style>
:root{--bg:#0B0B1A;--card:#1A1A3A;--line:#2A2A52;--text:#EDEBF7;--muted:#9D9BB8;--gold:#E8B84B;--purple:#9B59B6;--plum:#C39BD3;--good:#5FD39A;--bad:#F07C7C;color-scheme:dark}
body{background:var(--bg);color:var(--text);font:15px/1.55 Outfit,system-ui,sans-serif}
.w{max-width:680px;margin:0 auto;padding:28px 16px 56px;display:grid;gap:28px}
h1{font-size:30px;line-height:1.1;margin:0;font-weight:800;text-wrap:balance}h1 b{color:var(--gold)}
h2{font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--plum);margin:0 0 10px;font-weight:600}
p{margin:0;color:var(--muted)}p strong{color:var(--text)}
.eyebrow{font:500 12px 'JetBrains Mono',monospace;color:var(--muted);letter-spacing:.06em}
.num{font-family:'JetBrains Mono',ui-monospace,monospace;font-variant-numeric:tabular-nums}
.verdict{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px;display:grid;gap:12px}
.award{display:flex;justify-content:space-between;align-items:center;gap:12px}
.award .big{font:700 30px 'JetBrains Mono',monospace;color:var(--gold);white-space:nowrap}.award .big.zero{color:var(--muted)}
