// ─── Rule variants ───────────────────────────────────────────
// Each predicate decides whether a group of the team's matches counts as "the same roster".
// `core` = people present in every match of the group.
const intersect = (g) => g.map((m) => m.roster).reduce((a, r) => a.filter((x) => r.includes(x)));
const RULE_VARIANTS = [
  { key: "strict", name: "Identical roster", short: "Current rule",
    desc: "Exactly the same people in every counted match (the rule as written).",
    ok: (t, g) => g.every((m) => m.roster.length === g[0].roster.length && m.roster.every((u) => g[0].roster.includes(u))) },
  { key: "oneChange", name: "One change allowed",
    desc: "A core of at least 2 plays every match, and each lineup has at most 1 person outside that core.",
    ok: (t, g) => { const c = intersect(g); return c.length >= 2 && g.every((m) => m.roster.length - c.length <= 1); } },
  { key: "core3", name: "Core of 3", short: "Suggested",
    desc: "At least 3 people play every counted match (or the whole team, if it registered with fewer than 3).",
    ok: (t, g) => { const c = intersect(g); return c.length >= 2 && c.length >= Math.min(3, ...g.map((m) => m.roster.length)); } },
  { key: "majority", name: "Majority stays",
    desc: "A core of at least 2 plays every match and is at least half of every lineup.",
    ok: (t, g) => { const c = intersect(g); return c.length >= 2 && g.every((m) => c.length * 2 >= m.roster.length); } },
  { key: "presPlus1", name: "President + 1",
    desc: "The president and at least one teammate play every counted match.",
    ok: (t, g) => { const c = intersect(g); return c.length >= 2 && c.includes(t.president); } },
];
const SUGGESTED = "core3";

// ─── Analysis ────────────────────────────────────────────────
function analyse(d) {
  const counted = d.chapters.filter((c) => c.status === "completed" && !(EXCLUDE_FINALE && c.is_finale));
  const ch = Object.fromEntries(counted.map((c) => [c.id, c]));
  const email = Object.fromEntries(d.profiles.map((p) => [p.id, (p.email || "").toLowerCase().trim()]));
  const teamName = Object.fromEntries(d.teams.map((t) => [t.id, t.name]));
  const president = Object.fromEntries(d.teams.map((t) => [t.id, t.president_user_id]));
  const reconChapters = new Set(Object.keys(d.checkedInApps));

  function rosterFor(r) {
    if (r.roster && r.roster.length) return { roster: [...r.roster].sort(), recon: false };
    // Reconstruct: imported members still on the team + people who were later removed or
    // moved off the team and checked in at that event.
    const checked = new Set(d.checkedInApps[r.chapter_id] || []);
    const imported = d.members
      .filter((m) => m.team_id === r.team_id && m.joined_at.startsWith(MAKEATHON_IMPORT_DATE))
      .map((m) => m.user_id);
    const gone = [
      ...d.events.filter((e) => e.action === "team.member_removed" && e.entity_id === r.team_id)
        .map((e) => e.delta?.deleted?.user_id),
      ...d.events.filter((e) => e.action === "team.member_moved" && e.delta?.moved?.from_team === r.team_id)
        .map((e) => e.delta?.moved?.user_id),
    ].filter((u) => u && checked.has(email[u]));
    return { roster: [...new Set([...imported, ...gone])].sort(), recon: true };
  }

  const byTeam = {};
  for (const r of d.regs) {
    const c = ch[r.chapter_id];
    if (!c) continue;
    const s = d.scores.find((x) => x.team_id === r.team_id && x.chapter_id === r.chapter_id);
    (byTeam[r.team_id] ??= []).push({
      m: c.match_number, city: c.city, country: c.country, finale: !!c.is_finale,
      ...rosterFor(r), points: s?.points ?? null, placement: s?.placement ?? null,
    });
  }
  const teams = Object.entries(byTeam).map(([id, ms]) => ({
    id, name: teamName[id], president: president[id], matches: ms.sort((a, b) => a.m - b.m),
  }));

  const overlap = (a, b) => a.filter((x) => b.includes(x)).length;
  const kind = (a, b) => {
    const o = overlap(a, b);
    return o === a.length && o === b.length ? "identical" : o === 0 ? "none" : o === 1 ? "onlyOne" : "partial";
  };
  const emptyKinds = () => ({ identical: 0, partial: 0, onlyOne: 0, none: 0 });

  // Per team: each step to the team's NEXT played match
  const transitions = emptyKinds();
  const returning = teams.filter((t) => t.matches.length > 1).map((t) => {
    const steps = t.matches.slice(1).map((m, i) => {
      const prev = t.matches[i];
      const k = kind(prev.roster, m.roster);
      transitions[k]++;
      const kept = overlap(prev.roster, m.roster);
      return { from: prev.m, to: m.m, kept, added: m.roster.length - kept, dropped: prev.roster.length - kept, kind: k };
    });
    return {
      id: t.id, name: t.name, matches: t.matches.map((m) => m.m), sizes: t.matches.map((m) => m.roster.length),
      countries: [...new Set(t.matches.map((m) => m.country))], steps,
      core: intersect(t.matches).length,
      firstLastKept: overlap(t.matches[0].roster, t.matches.at(-1).roster),
      allIdentical: steps.every((s) => s.kind === "identical"),
    };
  });

  // Per match overview + transition into it
  const seen = new Set(); // people who played any earlier counted match
  const teamOfPersonAt = {}; // match -> user -> team
  const perMatch = counted.map((c, idx) => {
    const here = teams.flatMap((t) => t.matches.filter((m) => m.m === c.match_number).map((m) => ({ t, m })));
    const people = here.flatMap((x) => x.m.roster);
    const map = (teamOfPersonAt[c.match_number] = {});
    here.forEach((x) => x.m.roster.forEach((u) => (map[u] = x.t.id)));
    const prevTeamOf = (u) => { for (let j = idx - 1; j >= 0; j--) { const t = teamOfPersonAt[counted[j].match_number][u]; if (t) return t; } return null; };
    const veterans = people.filter((u) => seen.has(u));
    const switched = veterans.filter((u) => prevTeamOf(u) !== map[u]);
    const returningHere = here.filter((x) => x.t.matches[0].m !== c.match_number);
    const steps = returning.flatMap((r) => r.steps.filter((s) => s.to === c.match_number));
    const kinds = emptyKinds(); steps.forEach((s) => kinds[s.kind]++);
    // Of the previous counted match's teams, how many play here?
    const prev = counted[idx - 1];
    const prevTeams = prev ? teams.filter((t) => t.matches.some((m) => m.m === prev.match_number)) : [];
    const fromPrev = prevTeams.filter((t) => t.matches.some((m) => m.m === c.match_number)).length;
    const later = counted.slice(idx + 1).map((x) => x.match_number);
    const comeBackLater = here.filter((x) => x.t.matches.some((m) => later.includes(m.m))).length;
    const out = {
      m: c.match_number, city: c.city, country: c.country, date: c.date, finale: !!c.is_finale,
      reconstructed: reconChapters.has(c.id),
      teams: here.length, people: people.length,
      avgSize: here.length ? people.length / here.length : 0,
      newTeams: here.length - returningHere.length, returningTeams: returningHere.length,
      veterans: veterans.length, switchedTeam: switched.length, newPeople: people.length - veterans.length,
      arrivals: { kinds, kept: steps.reduce((s, x) => s + x.kept, 0), added: steps.reduce((s, x) => s + x.added, 0), dropped: steps.reduce((s, x) => s + x.dropped, 0) },
      fromPrevTeams: prev ? { prevM: prev.match_number, of: prevTeams.length, back: fromPrev } : null,
      comeBackLater, isLast: !later.length,
    };
    people.forEach((u) => seen.add(u));
    return out;
  });

  // Bonus under each rule variant
  const combos = (a, k) => (k === 0 ? [[]] : a.flatMap((x, i) => combos(a.slice(i + 1), k - 1).map((c) => [x, ...c])));
  const seasonSize = counted.length;
  function bonus(t, ok) {
    if (t.matches.length === seasonSize && ok(t, t.matches)) return RULES.fullSeason.points;
    for (const g of combos(t.matches, RULES.threeMatch.matches))
      if (new Set(g.map((m) => m.country)).size >= RULES.threeMatch.countries && ok(t, g)) return RULES.threeMatch.points;
    return 0;
  }
  const rank = (rows) => {
    rows = [...rows].sort((a, b) => b.pts - a.pts || (a.best ?? 99) - (b.best ?? 99) || a.name.localeCompare(b.name));
    let rk = 1;
    rows.forEach((r, i) => { if (i && (r.pts !== rows[i - 1].pts || r.best !== rows[i - 1].best)) rk = i + 1; r.rank = rk; });
    return rows;
  };
  // NOTE: the leaderboard view sums ALL published scores, including chapters excluded above.
  const lbRows = d.lb.map((r) => ({ id: r.team_id, name: r.team_name, pts: r.total_points, best: r.best_finish, bonus: 0 }));
  const base = rank(lbRows);
  const inTop = (rows) => new Set(rows.filter((r) => r.rank <= FINALE_SPOTS).map((r) => r.id));
  const scenarios = {};
  for (const v of RULE_VARIANTS) {
    const b = Object.fromEntries(teams.map((t) => [t.id, bonus(t, v.ok)]));
    const table = rank(lbRows.map((r) => ({ ...r, bonus: b[r.id] || 0, pts: r.pts + (b[r.id] || 0) })));
    const before = inTop(base), after = inTop(table);
    const awards = teams.filter((t) => b[t.id]).map((t) => ({ id: t.id, name: t.name, bonus: b[t.id] }));
    scenarios[v.key] = {
      key: v.key, name: v.name, short: v.short, desc: v.desc, awards, table,
      counts: { full: awards.filter((x) => x.bonus === RULES.fullSeason.points).length, three: awards.filter((x) => x.bonus === RULES.threeMatch.points).length, none: teams.length - awards.length },
      pointsAwarded: awards.reduce((s, x) => s + x.bonus, 0),
      enteredTop: table.filter((r) => after.has(r.id) && !before.has(r.id)).map((r) => r.name),
      leftTop: base.filter((r) => before.has(r.id) && !after.has(r.id)).map((r) => r.name),
    };
  }

  const multiCountry3 = teams.filter((t) => t.matches.length >= 3 && new Set(t.matches.map((m) => m.country)).size >= 2);
  const funnel = [
    { label: "played at least one match", n: teams.length },
    { label: "played 2+ matches", n: returning.length },
    { label: `played ${RULES.threeMatch.matches}+ matches in ${RULES.threeMatch.countries}+ countries`, n: multiCountry3.length },
    { label: `played all ${seasonSize} matches`, n: teams.filter((t) => t.matches.length === seasonSize).length },
    { label: "receive a bonus under the current rule", n: scenarios.strict.awards.length },
  ];
  const nearMiss = returning.filter((r) => r.allIdentical && !scenarios.strict.awards.some((a) => a.id === r.id));

  return {
    generatedAt: new Date().toISOString(), fetchedAt: d.fetchedAt,
    countedMatches: counted.map((c) => ({ m: c.match_number, city: c.city, country: c.country, finale: !!c.is_finale, date: c.date })),
    reconstructedMatches: counted.filter((c) => reconChapters.has(c.id)).map((c) => c.match_number),
    stats: {
      teamsTotal: d.teams.length, teamsPlayed: teams.length,
      playedOnce: teams.filter((t) => t.matches.length === 1).length, returning: returning.length,
      byMatchCount: teams.reduce((m, t) => ((m[t.matches.length] = (m[t.matches.length] || 0) + 1), m), {}),
      transitions,
      completeChangeTeams: returning.filter((r) => r.steps.some((s) => s.kind === "none")).map((r) => r.name),
      onlyOneKeptTeams: returning.filter((r) => r.steps.some((s) => s.kind === "onlyOne")).map((r) => r.name),
      identicalTeams: returning.filter((r) => r.allIdentical).map((r) => r.name),
      firstVsLastNoOverlap: returning.filter((r) => r.firstLastKept === 0).map((r) => r.name),
    },
    perMatch, funnel, teams, returning, base, scenarios, nearMiss,
  };
}

// ─── HTML ────────────────────────────────────────────────────
function render(a) {
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const list = (xs) => (xs.length ? xs.map(esc).join(", ") : "none");
  const pct = (n, of) => (of ? Math.round((100 * n) / of) + "%" : "–");
  const S = a.scenarios, cur = S.strict, sug = S[SUGGESTED];
  const baseRank = Object.fromEntries(a.base.map((r) => [r.id, r.rank]));
  const rowsShown = Math.max(FINALE_SPOTS + 5, 20);
  const K = { identical: ["same", "var(--gold)"], partial: ["2+ kept", "var(--purple)"], onlyOne: ["1 kept", "var(--bad)"], none: ["all new", "var(--grey)"] };
  const bar = (kinds) => {
    const tot = Object.values(kinds).reduce((s, x) => s + x, 0);
    if (!tot) return `<p class="note">No team arrived from an earlier match.</p>`;
    return `<div class="bar">${Object.entries(kinds).filter(([, v]) => v).map(([k, v]) => `<i style="flex:${v};background:${K[k][1]}" title="${v} ${K[k][0]}"></i>`).join("")}</div>
<div class="legend">${Object.entries(kinds).map(([k, v]) => `<span style="--c:${K[k][1]}"><b class="num">${v}</b> ${K[k][0]}</span>`).join("")}</div>`;
  };
  const table = (rows) => `<div class="tw"><table><thead><tr><th>#</th><th>Team</th><th class="r">Pts</th><th class="r">Move</th></tr></thead><tbody>${rows.slice(0, rowsShown).map((r) => {
    const dlt = baseRank[r.id] - r.rank;
    const mv = dlt > 0 ? `<span class="up">▲${dlt}</span>` : dlt < 0 ? `<span class="down">▼${-dlt}</span>` : `<span class="flat">–</span>`;
    return `<tr class="${r.bonus ? "hl" : ""}${r.rank > FINALE_SPOTS ? " out" : ""}"><td class="num">${r.rank}</td><td>${esc(r.name)}${r.bonus ? ` <span class="chip">+${r.bonus}</span>` : ""}</td><td class="r num">${r.pts}</td><td class="r num">${mv}</td></tr>`;
  }).join("")}</tbody></table></div>`;
  const top = (sc) => (sc.enteredTop.length || sc.leftTop.length ? `in: ${list(sc.enteredTop)} · out: ${list(sc.leftTop)}` : "unchanged");

  // Match cards with the transition into each match
  const matchCards = a.perMatch.map((pm, i) => {
    const tr = i === 0 ? "" : `
<div class="flow">
  <div class="flowhead"><span class="num">M${a.perMatch[i - 1].m}</span> → <span class="num">M${pm.m}</span></div>
  <div class="kv">
    <div><b class="num">${pm.fromPrevTeams.back}</b><span>of ${pm.fromPrevTeams.of} M${pm.fromPrevTeams.prevM} teams play again (${pct(pm.fromPrevTeams.back, pm.fromPrevTeams.of)})</span></div>
    <div><b class="num">${pm.returningTeams}</b><span>returning teams at M${pm.m}, from any earlier match</span></div>
  </div>
  <p class="sub">Their rosters, compared with each team's previous match:</p>
  ${bar(pm.arrivals.kinds)}
  <p class="sub">People in those teams: <b class="num">${pm.arrivals.kept}</b> stayed · <b class="num add">+${pm.arrivals.added}</b> joined · <b class="num rem">−${pm.arrivals.dropped}</b> left</p>
</div>`;
    return `${tr}
<article class="match">
  <header><div><span class="mn num">M${pm.m}</span> <strong>${esc(pm.city)}</strong> <span class="muted">${esc(pm.country)}${pm.finale ? " · Finale" : ""}</span></div><span class="muted num">${esc(pm.date ?? "")}</span></header>
  <div class="grid4">
