2	 * RSVP counters for the admin applications page.
3	 *
4	 * Pure and shared so the numbers on the screen cannot drift from what the
5	 * "Send RSVP Request" button actually does. The subtle one is `notAsked`: it
6	 * counts ONLY status "accepted", exactly the set sendRsvpEmails() mails.
7	 * Including checked-in applicants there would display work the button can never
8	 * clear (they have already arrived, so they are never sent a request), leaving a
9	 * number that never moves no matter how often an admin presses it.
10	 *
11	 * CANCELLED applicants are excluded from every count. They are not coming, and
12	 * that was settled outside the RSVP flow, so counting them distorts exactly the
13	 * numbers this board exists to give: a cancelled person who never answered sits
14	 * in "Awaiting" for ever (they never will), and one who had answered "yes"
15	 * inflates the headcount. Their row is deliberately kept in the database, so the
16	 * record that they were asked survives and a later send cannot re-mail them.
17	 */
18	
19	export interface RsvpCountable {
20	  status: string;
21	  rsvp?: { response: "yes" | "no" | null } | null;
22	}
23	
24	export interface RsvpCounts {
25	  /** Answered yes. Counts a checked-in person's earlier yes, never a cancelled one. */
26	  confirmed: number;
27	  /** Answered no. Same scoping as `confirmed`. */
28	  declined: number;
29	  /** Asked (a row exists), still unanswered, and still actually coming. */
30	  awaiting: number;
31	  /** Accepted and never asked. Equals what the next send will target. */
32	  notAsked: number;
33	}
34	
35	export function countRsvps(applications: RsvpCountable[]): RsvpCounts {
36	  let confirmed = 0;
37	  let declined = 0;
38	  let awaiting = 0;
39	  let notAsked = 0;
40	
41	  for (const app of applications) {
42	    // Cancelled applicants are out of the picture entirely, answered or not.
43	    if (app.status === "cancelled") continue;
44	
45	    if (app.rsvp) {
46	      if (app.rsvp.response === "yes") confirmed++;
47	      else if (app.rsvp.response === "no") declined++;
48	      else awaiting++;
49	    } else if (app.status === "accepted") {
50	      notAsked++;
51	    }
52	  }
53	
54	  return { confirmed, declined, awaiting, notAsked };
